package vn.edu.webpro.robotlab.controller;
import java.io.IOException;import java.sql.SQLException;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import vn.edu.webpro.robotlab.dao.*;import vn.edu.webpro.robotlab.service.LibraryResourceService;import vn.edu.webpro.robotlab.web.*;
@WebServlet("/api/library-resources") public final class LibraryResourceServlet extends HttpServlet{private final LibraryResourceService service=new LibraryResourceService(new LibraryResourceDao(new DatabaseConnectionFactory(System.getenv())));@Override protected void doGet(HttpServletRequest req,HttpServletResponse res)throws IOException{try{int page=num(req,"page",1),limit=num(req,"limit",20);String robotId=req.getParameter("robotId");var data=service.list(page,limit,robotId);String json=data.stream().map(item->item.toJson()).reduce((a,b)->a+","+b).orElse("");ApiResponses.json(res,200,"{\"data\":["+json+"],\"meta\":{\"page\":"+page+",\"limit\":"+limit+",\"total\":"+service.count(robotId)+"}}");}catch(IllegalArgumentException e){ApiResponses.error(res,422,"VALIDATION_ERROR","Phân trang không hợp lệ.");}catch(SQLException e){ApiResponses.error(res,503,"DEPENDENCY_NOT_READY","Cơ sở dữ liệu chưa được cấu hình.");}}private int num(HttpServletRequest r,String k,int d){String v=r.getParameter(k);if(v==null)return d;try{return Integer.parseInt(v);}catch(NumberFormatException e){throw new IllegalArgumentException();}}}
